//version 6.5.4 Same thing in version 4.0.0-rc.1
async function applyFilter(canvas: Fabric.Canvas, index: number, filter: any) {
  const obj: any = canvas.getActiveObject();

  if (obj && obj.type === "image") {
    obj.filters[index] = filter;
    obj.applyFilters();
    canvas.renderAll();
  }
}


function applyFilterValue(
  canvas: Fabric.Canvas,
  index: number,
  prop: string,
  value: any
): void {
  console.log(prop, value);
  const obj: any = canvas.getActiveObject();
  if (obj?.filters[index]) {
    obj.filters[index][prop] = value;
    obj.applyFilters();
    canvas.renderAll();
  }
}

//USE
function applyBrightness(canvas: Fabric.Canvas, brightness: number): void {
  var current: any = canvas.getActiveObject();
  !current.filters[5] ? applyFilter(canvas, 5, new Fabric.filters.Brightness({ brightness })) : null;
  applyFilterValue(canvas, 5, indexFilters[5], brightness);
}
`

